function snakeKeys(obj) {
  const result = {};
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    const snake = key.replace(/([a-z])([A-Z])/g, "$1_$2").toLowerCase();
    result[snake] = obj[key];
  }
  return result;
}
